class Solution {
    bool valid(const string& s,const string& t,int k){
        int j=0;for(char c:s)if(c==t[j%t.size()]){
            ++j;if(j==(int)t.size()*k)return true;
        }
        return false;
    }
public:
    string longestSubsequenceRepeatedK(string s,int k){
        int freq[26]={};for(char c:s)++freq[c-'a'];
        string alphabet;for(int i=0;i<26;++i)if(freq[i]>=k)alphabet+=char('a'+i);
        queue<string>q;q.push("");string ans;
        while(!q.empty()){
            string cur=q.front();q.pop();
            for(char c:alphabet){string next=cur+c;
                if(valid(s,next,k)){ans=next;q.push(next);}
            }
        }
        return ans;
    }
};
